INSERT INTO notices ("id", "title", "content", "category", "image_url", "is_pinned", "is_visible", "view_count", "created_at", "display_date") VALUES ('9356ed26-d892-426d-b13a-cb90ae3bf5c8', '📢 고객센터 운영 안내', '고객센터 운영시간은 평일 오전 10시부터 오후 6시까지입니다. 주말 및 공휴일 문의는 순차적으로 답변드리고 있으니 양해 부탁드립니다.
INSERT INTO notices ("id", "title", "content", "category", "image_url", "is_pinned", "is_visible", "view_count", "created_at", "display_date") VALUES ('bb719b67-6130-4363-b6c2-cb73389d2e40', '📢 주문 전 필독 안내', '주문 전 상품명, 옵션, 사이즈 및 상세 정보를 반드시 확인해 주시기 바랍니다. 단순 변심에 의한 취소 및 변경은 제한될 수 있습니다.
INSERT INTO notices ("id", "title", "content", "category", "image_url", "is_pinned", "is_visible", "view_count", "created_at", "display_date") VALUES ('c8220694-1d04-40f9-9b7e-eda773e78b7e', '📢 신규 회원 혜택 안내', '회원가입 시 즉시 사용 가능한 적립금과 다양한 이벤트 혜택을 제공해 드립니다. 자세한 내용은 이벤트 게시판을 확인해 주세요.', 'general', NULL, FALSE, TRUE, 22584, '2026-06-06T07:32:30.525404', '2025-01-05T04:32:00') ON CONFLICT DO NOTHING;
INSERT INTO notices ("id", "title", "content", "category", "image_url", "is_pinned", "is_visible", "view_count", "created_at", "display_date") VALUES ('ed9b5e14-c3e0-4b9d-ac29-6e6b12c8e081', ' 📢 배송 안내', '주문량 증가로 인해 일부 상품의 입고 및 배송 기간이 평소보다 다소 지연될 수 있습니다. 정확한 배송 현황은 고객센터를 통해 문의 부탁드립니다.', 'general', NULL, FALSE, TRUE, 22847, '2026-06-06T07:32:42.089859', '2025-01-05T04:32:00') ON CONFLICT DO NOTHING;
